const payload = $input.first().json.body?.payload || $input.first().json.payload || {};
const segments = payload.segments || {};
const suggestions = payload.suggestions || [];
const tenant_id = $input.first().json.body?.tenant_id || $input.first().json.tenant_id || '';
const timestamp = $input.first().json.body?.timestamp || $input.first().json.timestamp || '';

let csv = 'Segment,Count,Channel,Message\n';
for (const [seg, data] of Object.entries(segments)) {
  const count = typeof data === 'object' ? (data.count || data.leads?.length || 0) : data;
  const suggestion = suggestions.find(s => s.segment === seg) || {};
  csv += `${seg},${count},${suggestion.channel || 'N/A'},${(suggestion.message || 'N/A').replace(/,/g, ';')}\n`;
}

const ts = new Date().toISOString().split('T')[0];
const filename = `marketing_report_${ts}.csv`;
const csvB64 = Buffer.from(csv).toString('base64');

const boundary = '----=_Part_IREIOS_' + Date.now();
const to = 'maitridj01@gmail.com';
const now = new Date();
const ist = new Date(now.getTime() + (5.5 * 60 * 60 * 1000));
const dateStr = ist.toISOString().split('T')[0].split('-').reverse().join('-');
const subjectPlain = `Weekly Marketing Report - ${dateStr}`;
const subjectEncoded = '=?UTF-8?B?' + Buffer.from(subjectPlain).toString('base64') + '?=';
const htmlBody = `<h2>Weekly Marketing Report</h2><p>Report generated for <b>${tenant_id}</b>.</p><p>Segments:</p><ul><li>Hot: ${segments.hot?.count || 0}</li><li>Warm: ${segments.warm?.count || 0}</li><li>Cold: ${segments.cold?.count || 0}</li></ul><p>CSV file attached.</p>`;

const mimeMessage = [
  `To: ${to}`,
  `Subject: ${subjectEncoded}`,
  'MIME-Version: 1.0',
  `Content-Type: multipart/mixed; boundary="${boundary}"`,
  '',
  `--${boundary}`,
  'Content-Type: text/html; charset=UTF-8',
  '',
  htmlBody,
  '',
  `--${boundary}`,
  'Content-Type: text/csv; name="' + filename + '"',
  'Content-Transfer-Encoding: base64',
  `Content-Disposition: attachment; filename="${filename}"`,
  '',
  csvB64,
  `--${boundary}--`
].join('\r\n');

const rawB64 = Buffer.from(mimeMessage).toString('base64');

return [{
  json: {
    tenant_id,
    timestamp,
    segments,
    filename,
    raw: rawB64
  }
}];
